import{c as t,Q as a,j as i,m as l}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"SkillRAE: Agent Skill-Based Context Compilation for Retrieval-Augmented Execution","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.10114","title":"SkillRAE: Agent Skill-Based Context Compilation for Retrieval-Augmented Execution","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2605.10114,"authors":["Xiangcheng Meng","Shu Wang","Yixiang Fang"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2605.10114v1","pdf_path":"pdfs/2605.10114.pdf","published_date":"2026-05-11T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-11-skillrae-skill-context-compilation-rae-2605-10114.md","filePath":"research/papers/2026-05-11-skillrae-skill-context-compilation-rae-2605-10114.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-05-11-skillrae-skill-context-compilation-rae-2605-10114.md"};function r(s,e,n,c,h,p){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="skillrae-agent-skill-based-context-compilation-for-retrieval-augmented-execution" tabindex="-1">SkillRAE: Agent Skill-Based Context Compilation for Retrieval-Augmented Execution <a class="header-anchor" href="#skillrae-agent-skill-based-context-compilation-for-retrieval-augmented-execution" aria-label="Permalink to &quot;SkillRAE: Agent Skill-Based Context Compilation for Retrieval-Augmented Execution&quot;">​</a></h1><p><strong>Authors</strong>: Xiangcheng Meng, Shu Wang, Yixiang Fang <strong>Published</strong>: May 11, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.10114" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.10114</a> · <a href="https://arxiv.org/html/2605.10114v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2605.10114 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.10114" target="_blank" rel="noreferrer">research/papers/pdfs/2605.10114.pdf</a> (16 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large Language Model (LLM)-based agents (e.g., OpenClaw) increasingly rely on reusable skill libraries to solve artifact-rich tasks such as document-centric workflows and data-intensive analysis. As these libraries grow, a few works have attempted to study the Retrieval-Augmented Execution (RAE), which often first retrieves some external skills and other knowledge, then compiles the context using retrieved skills, and finally executes the task. Existing works mainly focus on optimizing skill retrieval and task execution, and they pay little attention to how to effectively organize the selected skill evidence in a form that is compact, grounded, and immediately usable for the downstream executors to complete tasks. To fill this gap, we propose SkillRAE, a two-stage RAE approach focusing on skill-based context compilation, which consists of the offline and online stages. Specifically, in the offline indexing stage, it builds a multi-level skill graph over skill communities, skills, and reusable subunits, for capturing their relationships. In the online retrieval stage, it first performs skill-ranked retrieval with selected-subunit evidence export in the graph, and then applies rescue-aware compact compilation to recover the key evidence. Together, these components compile a coarse-ranked skill set into a task-specific context that is compact, grounded, and immediately usable. Experiments on two public benchmarks show that SkillRAE achieves a significant improvement over baselines for RAE. For example, on SkillsBench, it achieves an improvement of 11.7% over the SOTA method. Ablation studies further show that our context compilation is crucial, instead of a mere prompt addition.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>RAE（Retrieval-Augmented Execution）的「skill 證據組織」缺口：現有只優化 retrieval/execution，忽略把選中 skill 組成 compact/grounded/即用的 context。兩階段：</p><ol><li><strong>Offline indexing</strong> — 建 multi-level skill graph（skill communities → skills → reusable subunits）捕捉關係。</li><li><strong>Online retrieval</strong> — skill-ranked retrieval + selected-subunit 證據匯出 → <strong>rescue-aware compact compilation</strong> 救回關鍵證據，編成 task-specific compact context。</li></ol><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>兩 benchmark 顯著超基線；SkillsBench 上超 SOTA <strong>+11.7%</strong>。Ablation：context compilation 關鍵（非單純 prompt 添加）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>16 pp；offline skill graph 需語料規模支撐，小型 skill 庫收益待評估。</li></ul><h3 id="命名注意" tabindex="-1">命名注意 <a class="header-anchor" href="#命名注意" aria-label="Permalink to &quot;命名注意&quot;">​</a></h3><ul><li>abstract 提及 &quot;OpenClaw&quot; 等為論文示例 agent 名（模擬時間軸），非本 workspace 元件。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>對應 harness-synthesis §7 SkillRAE 候選</strong>：本 workspace 28 skills lazy-load，SkillRAE 的 skill-graph 選擇性載入是「多 skill 載入 token 膨脹」的進階解；但審計指 28 skills 規模偏小，<strong>收益待實測</strong>（列低優先）。</li><li><strong>rescue-aware compact compilation ↔ context-management</strong>：compact 但保關鍵證據，呼應 ACE 防 context collapse、pre-compact.sh HEAD/TAIL/MIDDLE。</li><li><strong>multi-level skill graph ↔ RESOLVER.md</strong>：本 workspace 已有 RESOLVER 路由表（人工），SkillRAE 是其自動化/圖化方向參考。</li><li>⚠️ 與 SkillCAT TTE topology 同屬「skill 拓撲化載入」線；兩者可對照但落地皆需 skill 規模門檻。</li></ul>',19)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
